#include <iostream>
#include <list>
using namespace std;

int main() {
    list<string> names = {"Ali", "Sara", "Ahmed"};

    // Add elements
    names.push_back("Fatima");  // End
    names.push_front("Zain");   // Beginning

    // Remove
    names.remove("Ahmed");

    // Display
    for(string name : names) {
        cout << name << " ";
    }

    cout << "\nFront: " << names.front();
    cout << "\nBack: " << names.back();

