#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    cout << "=== C++ STL Algorithms ===" << endl;

    // Sorting Algorithms
    cout << "\n--- Sorting Algorithms ---" << endl;

    vector<int> numbers = {5, 2, 8, 1, 9, 3, 7, 4, 6};
    vector<string> fruits = {"banana", "apple", "orange", "grape", "mango"};

    // Basic sort (ascending)
    sort(numbers.begin(), numbers.end());
    cout << "Sorted numbers (ascending): ";
    for (int n : numbers) cout << n << " ";
    cout << endl;

    // Sort strings alphabetically
    sort(fruits.begin(), fruits.end());
    cout << "Sorted fruits: ";
    for (string f : fruits) cout << f << " ";
    cout << endl;

    // Sort descending
    sort(numbers.rbegin(), numbers.rend());
    cout << "Sorted numbers (descending): ";
    for (int n : numbers) cout << n << " ";
    cout << endl;

    // Partial sort (first 3 elements)
    numbers = {9, 2, 5, 1, 8, 3, 7, 4, 6};
    partial_sort(numbers.begin(), numbers.begin() + 3, numbers.end());
    cout << "First 3 sorted elements: ";
    for (int n : numbers) cout << n << " ";
    cout << endl;

    // Searching Algorithms
    cout << "\n--- Searching Algorithms ---" << endl;

    numbers = {1, 3, 5, 7, 9, 2, 4, 6, 8};

    // Find specific value
    auto it = find(numbers.begin(), numbers.end(), 5);
    if (it != numbers.end()) {
        cout << "Found 5 at position: " << distance(numbers.begin(), it) << endl;
    }

    // Find if condition matches
    it = find_if(numbers.begin(), numbers.end(), [](int n) {
        return n > 6;
    });
    if (it != numbers.end()) {
        cout << "First number > 6: " << *it << endl;
    }

    // Binary search (requires sorted data)
    sort(numbers.begin(), numbers.end());
    bool found = binary_search(numbers.begin(), numbers.end(), 7);
    cout << "Binary search for 7: " << (found ? "Found" : "Not found") << endl;

    // Lower and upper bound
    it = lower_bound(numbers.begin(), numbers.end(), 5);
    cout << "Lower bound of 5: " << *it << endl;

    it = upper_bound(numbers.begin(), numbers.end(), 5);
    cout << "Upper bound of 5: " << *it << endl;

    // Min/Max Algorithms
    cout << "\n--- Min/Max Algorithms ---" << endl;

    numbers = {4, 2, 9, 1, 7, 3};

    auto min_it = min_element(numbers.begin(), numbers.end());
    auto max_it = max_element(numbers.begin(), numbers.end());

    cout << "Minimum element: " << *min_it << endl;
    cout << "Maximum element: " << *max_it << endl;

    int a = 10, b = 20;
    cout << "Min of 10 and 20: " << min(a, b) << endl;
    cout << "Max of 10 and 20: " << max(a, b) << endl;

    // Modifying Algorithms
    cout << "\n--- Modifying Algorithms ---" << endl;

    vector<int> source = {1, 2, 3, 4, 5};
    vector<int> destination(5);

    // Copy elements
    copy(source.begin(), source.end(), destination.begin());
    cout << "Copied vector: ";
    for (int n : destination) cout << n << " ";
    cout << endl;

    // Fill with value
    fill(destination.begin(), destination.end(), 0);
    cout << "Filled with zeros: ";
    for (int n : destination) cout << n << " ";
    cout << endl;

    // Generate values
    vector<int> generated(5);
    int counter = 1;
    generate(generated.begin(), generated.end(), [&counter]() {
        return counter++ * 10;
    });
    cout << "Generated numbers: ";
    for (int n : generated) cout << n << " ";
    cout << endl;

    // Remove elements
    vector<int> with_duplicates = {1, 2, 2, 3, 4, 4, 5};
    auto new_end = unique(with_duplicates.begin(), with_duplicates.end());
    with_duplicates.erase(new_end, with_duplicates.end());
    cout << "After removing duplicates: ";
    for (int n : with_duplicates) cout << n << " ";
    cout << endl;

    // Counting Algorithms
    cout << "\n--- Counting Algorithms ---" << endl;

    numbers = {1, 2, 3, 2, 4, 2, 5};

    int count_2 = count(numbers.begin(), numbers.end(), 2);
    cout << "Number 2 appears " << count_2 << " times" << endl;

    int count_even = count_if(numbers.begin(), numbers.end(), [](int n) {
        return n % 2 == 0;
    });
    cout << "Even numbers: " << count_even << endl;

    // Numeric Algorithms
    cout << "\n--- Numeric Algorithms ---" << endl;

    numbers = {1, 2, 3, 4, 5};

    int sum = accumulate(numbers.begin(), numbers.end(), 0);
    cout << "Sum of numbers: " << sum << endl;

    int product = accumulate(numbers.begin(), numbers.end(), 1, multiplies<int>());
    cout << "Product of numbers: " << product << endl;

    // Transform (apply function to each element)
    cout << "\n--- Transform Algorithm ---" << endl;

    vector<int> original = {1, 2, 3, 4, 5};
    vector<int> squared(original.size());

    transform(original.begin(), original.end(), squared.begin(), [](int n) {
        return n * n;
    });

    cout << "Original: ";
    for (int n : original) cout << n << " ";
    cout << endl;

    cout << "Squared: ";
    for (int n : squared) cout << n << " ";
    cout << endl;

    // Reverse Algorithm
    cout << "\n--- Reverse Algorithm ---" << endl;

    vector<int> to_reverse = {1, 2, 3, 4, 5};
    reverse(to_reverse.begin(), to_reverse.end());
    cout << "Reversed: ";
    for (int n : to_reverse) cout << n << " ";
    cout << endl;

    cout << "\n=== Algorithm Categories ===" << endl;
    cout << "1. Non-modifying: find, count, search" << endl;
    cout << "2. Modifying: copy, fill, transform" << endl;
    cout << "3. Sorting: sort, stable_sort, partial_sort" << endl;
    cout << "4. Binary Search: binary_search, lower_bound" << endl;
    cout << "5. Min/Max: min_element, max_element" << endl;
    cout << "6. Numeric: accumulate, inner_product" << endl;

    return 0;
}

