#include <iostream>
#include <string>
using namespace std;

// Basic namespace declaration
namespace MathOperations {
    const double PI = 3.14159;

    double add(double a, double b) {
        return a + b;
    }

    double multiply(double a, double b) {
        return a * b;
    }

    class Calculator {
    public:
        static double square(double x) {
            return x * x;
        }
    };
}

// Another namespace
namespace StringOperations {
    string toUpper(string str) {
        for (char &c : str) {
            c = toupper(c);
        }
        return str;
    }

    string toLower(string str) {
        for (char &c : str) {
            c = tolower(c);
        }
        return str;
    }
}

// Nested namespaces
namespace Company {
    namespace HR {
        class Employee {
        public:
            string name;
            int id;
            Employee(string n, int i) : name(n), id(i) {}
        };

        void showEmployee(Employee e) {
            cout << "ID: " << e.id << ", Name: " << e.name << endl;
        }
    }

    namespace Finance {
        double calculateTax(double salary) {
            return salary * 0.15;
        }
    }
}

// Global scope
int count = 100;  // Global variable

// Namespace with same variable name
namespace ProjectA {
    int count = 50;

    void display() {
        cout << "ProjectA count: " << count << endl;
        cout << "Global count: " << ::count << endl;  // Access global
    }
}

namespace ProjectB {
    int count = 75;
}

// Anonymous namespace (only accessible in this file)
namespace {
    int internalCounter = 0;

    void increment() {
        internalCounter++;
    }
}

int main() {
    cout << "=== C++ Namespaces ===" << endl;

    // Accessing namespace elements with scope resolution
    cout << "\n--- Using Scope Resolution (::) ---" << endl;

    cout << "Math PI: " << MathOperations::PI << endl;
    cout << "5 + 3 = " << MathOperations::add(5, 3) << endl;
    cout << "Square of 4: " << MathOperations::Calculator::square(4) << endl;

    string text = "Hello World";
    cout << "Uppercase: " << StringOperations::toUpper(text) << endl;
    cout << "Lowercase: " << StringOperations::toLower(text) << endl;

    // Using nested namespaces
    cout << "\n--- Nested Namespaces ---" << endl;
    Company::HR::Employee emp("Ali Khan", 101);
    Company::HR::showEmployee(emp);

    double salary = 50000;
    double tax = Company::Finance::calculateTax(salary);
    cout << "Tax on " << salary << " is: " << tax << endl;

    // Name conflict resolution
    cout << "\n--- Name Conflict Resolution ---" << endl;
    cout << "Global count: " << count << endl;
    cout << "ProjectA count: " << ProjectA::count << endl;
    cout << "ProjectB count: " << ProjectB::count << endl;

    ProjectA::display();

    // Using 'using' keyword
    cout << "\n--- Using 'using' Keyword ---" << endl;

    // Bring specific elements into current scope
    using MathOperations::PI;
    using MathOperations::add;

    cout << "Using PI directly: " << PI << endl;
    cout << "Using add directly: " << add(10, 20) << endl;

    // Bring entire namespace (use with caution!)
    {
        using namespace MathOperations;
        cout << "Inside block - Multiply: " << multiply(3, 4) << endl;
    }
    // multiply() not accessible here

    // The 'std' namespace example
    cout << "\n--- The std Namespace ---" << endl;

    // Method 1: Always use std::
    std::cout << "Using std::cout" << std::endl;
    std::string message1 = "Hello";

    // Method 2: Use 'using' for specific elements
    using std::cout;
    using std::endl;
    cout << "Using specific using statements" << endl;

    // Method 3: Using entire namespace (common in small programs)
    // using namespace std;
    // cout << "Entire namespace" << endl;

    // Namespace aliases
    cout << "\n--- Namespace Aliases ---" << endl;

    namespace MO = MathOperations;  // Create alias
    namespace SO = StringOperations;

    cout << "Using alias - PI: " << MO::PI << endl;
    cout << "Using alias - toUpper: " << SO::toUpper("test") << endl;

    // Anonymous namespace usage
    cout << "\n--- Anonymous Namespace ---" << endl;
    cout << "Initial counter: " << internalCounter << endl;
    increment();
    increment();
    cout << "After increments: " << internalCounter << endl;

    // Real-world simulation
    cout << "\n--- Real-World Simulation ---" << endl;

    namespace GraphicsLibrary {
        void drawCircle(int x, int y, int radius) {
            cout << "Drawing circle at (" << x << "," << y << ") with radius " << radius << endl;
        }

        void drawRectangle(int x, int y, int width, int height) {
            cout << "Drawing rectangle at (" << x << "," << y << ") size " << width << "x" << height << endl;
        }
    }

    namespace PhysicsLibrary {
        void calculateVelocity(double distance, double time) {
            cout << "Velocity: " << distance / time << " m/s" << endl;
        }

        void calculateForce(double mass, double acceleration) {
            cout << "Force: " << mass * acceleration << " N" << endl;
        }
    }

    // No conflict even with same function names!
    GraphicsLibrary::drawCircle(100, 100, 50);
    PhysicsLibrary::calculateVelocity(100, 10);

    cout << "\n=== Best Practices ===" << endl;
    cout << "1. Use namespaces to organize large projects" << endl;
    cout << "2. Avoid 'using namespace' in header files" << endl;
    cout << "3. Prefer 'using std::cout' over 'using namespace std'" << endl;
    cout << "4. Use descriptive namespace names" << endl;
    cout << "5. Use nested namespaces for better organization" << endl;

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

// Class to demonstrate multiple keywords
class Employee {
private:
    string name;
    int id;
    static int totalEmployees;  // static keyword

public:
    // Constructor
    Employee(string n, int i) : name(n), id(i) {
        totalEmployees++;
    }

    // Virtual function for polymorphism
    virtual void display() const {  // const keyword
        cout << "ID: " << id << ", Name: " << name << endl;
    }

    // Static method
    static int getTotalEmployees() {
        return totalEmployees;
    }

    // Friend function
    friend void showEmployeeDetails(const Employee& e);

    // Virtual destructor
    virtual ~Employee() {
        totalEmployees--;
    }
};

// Initialize static member
int Employee::totalEmployees = 0;

// Friend function definition
void showEmployeeDetails(const Employee& e) {
    cout << "Friend Function - " << e.name << " (" << e.id << ")" << endl;
}

// Derived class
class Manager : public Employee {  // public keyword for inheritance
private:
    string department;

public:
    Manager(string n, int i, string dept) 
        : Employee(n, i), department(dept) {}

    // Override base class method
    void display() const override {  // override keyword
        Employee::display();
        cout << "Department: " << department << endl;
    }
};

// Template function
template<typename T>  // template keyword
T getMax(T a, T b) {
    return (a > b) ? a : b;
}

// Enumeration
enum class Day {  // enum keyword
    Monday,
    Tuesday,
    Wednesday,
    Thursday,
    Friday,
    Saturday,
    Sunday
};

// Type alias using typedef
typedef unsigned long long ULL;

// Alternative type alias using using
using StringVector = vector<string>;

int main() {
    cout << "=== C++ Keywords Complete Guide ===" << endl;

    // Data type keywords
    cout << "\n--- Data Type Keywords ---" << endl;
    bool isActive = true;       // bool keyword
    char grade = 'A';           // char keyword
    int age = 25;               // int keyword
    float price = 99.99f;       // float keyword
    double pi = 3.14159;        // double keyword
    long bigNumber = 1000000L;  // long keyword

    // unsigned and signed
    unsigned int positiveOnly = 100;  // unsigned keyword
    signed int canBeNegative = -50;   // signed keyword

    cout << "bool: " << isActive << endl;
    cout << "char: " << grade << endl;
    cout << "int: " << age << endl;
    cout << "float: " << price << endl;
    cout << "double: " << pi << endl;

    // Control flow keywords
    cout << "\n--- Control Flow Keywords ---" << endl;

    // if, else
    if (age >= 18) {  // if keyword
        cout << "Adult" << endl;
    } else {          // else keyword
        cout << "Minor" << endl;
    }

    // switch, case, default
    int dayNumber = 3;
    switch (dayNumber) {  // switch keyword
        case 1:           // case keyword
            cout << "Monday" << endl;
            break;        // break keyword
        case 2:
            cout << "Tuesday" << endl;
            break;
        case 3:
            cout << "Wednesday" << endl;
            break;
        default:          // default keyword
            cout << "Other day" << endl;
            break;
    }

    // Loop keywords
    cout << "\n--- Loop Keywords ---" << endl;

    // for loop
    cout << "for loop: ";
    for (int i = 0; i < 5; i++) {  // for keyword
        cout << i << " ";
    }
    cout << endl;

    // while loop
    cout << "while loop: ";
    int count = 0;
    while (count < 3) {  // while keyword
        cout << count << " ";
        count++;
        continue;  // continue keyword (not necessary here, just demonstration)
    }
    cout << endl;

    // do-while loop
    cout << "do-while loop: ";
    count = 0;
    do {  // do keyword
        cout << count << " ";
        count++;
    } while (count < 3);  // while keyword
    cout << endl;

    // Function and return keywords
    cout << "\n--- Function Keywords ---" << endl;

    auto multiply = [](int a, int b) -> int {  // auto keyword (C++11)
        return a * b;  // return keyword
    };

    cout << "5 * 6 = " << multiply(5, 6) << endl;

    // void function
    auto greet = []() -> void {  // void keyword
        cout << "Hello!" << endl;
    };
    greet();

    // Memory management keywords
    cout << "\n--- Memory Management Keywords ---" << endl;

    // new and delete
    int* dynamicArray = new int[5];  // new keyword
    for (int i = 0; i < 5; i++) {
        dynamicArray[i] = i * 10;
    }
    cout << "Dynamic array: ";
    for (int i = 0; i < 5; i++) {
        cout << dynamicArray[i] << " ";
    }
    cout << endl;
    delete[] dynamicArray;  // delete keyword

    // Class and OOP keywords
    cout << "\n--- OOP Keywords ---" << endl;

    Employee emp1("Ali", 101);
    Manager mgr1("Sara", 102, "IT");

    emp1.display();
    mgr1.display();

    showEmployeeDetails(emp1);

    cout << "Total employees: " << Employee::getTotalEmployees() << endl;

    // Access modifiers
    cout << "\n--- Access Modifiers ---" << endl;
    cout << "public: Accessible from anywhere" << endl;
    cout << "private: Accessible only within class" << endl;
    cout << "protected: Accessible within class and derived classes" << endl;

    // const keyword
    cout << "\n--- const Keyword ---" << endl;
    const int MAX_SIZE = 100;  // const variable
    // MAX_SIZE = 200;  // Error: cannot modify const

    // volatile keyword (for hardware programming)
    volatile int hardwareRegister = 0;
    cout << "volatile variable: " << hardwareRegister << endl;

    // sizeof operator
    cout << "\n--- sizeof Operator ---" << endl;
    cout << "sizeof(int): " << sizeof(int) << " bytes" << endl;
    cout << "sizeof(double): " << sizeof(double) << " bytes" << endl;
    cout << "sizeof(Employee): " << sizeof(Employee) << " bytes" << endl;

    // typedef and using
    cout << "\n--- Type Aliases ---" << endl;
    ULL bigValue = 18446744073709551615ULL;
    cout << "ULL value: " << bigValue << endl;

    StringVector names = {"Ali", "Sara", "Ahmed"};
    cout << "StringVector: ";
    for (const auto& name : names) {
        cout << name << " ";
    }
    cout << endl;

    // Alternative tokens
    cout << "\n--- Alternative Tokens ---" << endl;
    bool a = true;
    bool b = false;

    // Traditional way
    if (a && b) {  // && operator
        cout << "Both true" << endl;
    }

    // Alternative way
    if (a and b) {  // and keyword
        cout << "Both true (using and)" << endl;
    }

    if (not a) {  // not keyword
        cout << "a is false" << endl;
    }

    // Exception handling keywords
    cout << "\n--- Exception Handling ---" << endl;
    try {  // try keyword
        int x = 10;
        int y = 0;

        if (y == 0) {
            throw runtime_error("Division by zero!");  // throw keyword
        }

        int result = x / y;
        cout << "Result: " << result << endl;
    } 
    catch (const exception& e) {  // catch keyword
        cout << "Error: " << e.what() << endl;
    }

    // Enum demonstration
    cout << "\n--- Enum Keyword ---" << endl;
    Day today = Day::Wednesday;
    switch (today) {
        case Day::Monday:
            cout << "It's Monday" << endl;
            break;
        case Day::Wednesday:
            cout << "It's Wednesday" << endl;
            break;
        default:
            cout << "Other day" << endl;
    }

    // Template demonstration
    cout << "\n--- Template Keyword ---" << endl;
    cout << "Max of 5 and 10: " << getMax(5, 10) << endl;
    cout << "Max of 3.14 and 2.71: " << getMax(3.14, 2.71) << endl;
    cout << "Max of 'a' and 'z': " << getMax('a', 'z') << endl;

    // this pointer
    cout << "\n--- this Pointer ---" << endl;
    class TestClass {
    public:
        void printAddress() {
            cout << "this address: " << this << endl;
        }
    };

    TestClass obj;
    obj.printAddress();

    // goto keyword (use sparingly!)
    cout << "\n--- goto Keyword ---" << endl;
    int i = 0;

    loop_start:
    if (i < 3) {
        cout << i << " ";
        i++;
        goto loop_start;  // goto keyword
    }
    cout << endl;

    cout << "\n=== Keyword Categories ===" << endl;
    cout << "1. Data Types: bool, char, int, float, double, void" << endl;
    cout << "2. Storage Classes: auto, static, register, extern" << endl;
    cout << "3. Control Flow: if, else, switch, case, default" << endl;
    cout << "4. Loops: for, while, do, break, continue" << endl;
    cout << "5. OOP: class, struct, public, private, protected" << endl;
    cout << "6. Inheritance: virtual, override, final" << endl;
    cout << "7. Memory: new, delete" << endl;
    cout << "8. Exception: try, catch, throw" << endl;
    cout << "9. Templates: template, typename, class" << endl;
    cout << "10. Others: const, volatile, sizeof, typedef" << endl;

    return 0;
}

