#include <concepts>
#include <type_traits>

template <typename T>
concept Addable = requires(T a, T b) {
    { a + b } -> std::convertible_to<T>;
};

template <Addable T>
constexpr T add(T a, T b) {
    return a + b;
}

int main() {
    static_assert(add(3, 5) == 8);
}

